    long long N = 0;
    cin >> N;
    bool first = true;
    for (long long p = 2; p * p <= N; p++) {
        if (N % p != 0)
            continue;
        int cnt = 0;
        while (N % p == 0) {
            cnt++;
            N /= p;
        }
        if (first) {
            first = false;
        } else {
            cout << " * ";
        }
        cout << p;
        if (cnt > 1)
            cout << "^" << cnt;
    }
    if (N > 1) {
        if (first) {
            first = false;
        } else {
            cout << " * ";
        }
        cout << N;
    }
    cout << endl;
    return 0;
}

#include <iostream>
#include <algorithm>
using namespace std;
int n = 0;
struct game_t {
    int T, R;
} games[500];
bool game_cmp(game_t x, game_t y){
    return x.R > y.R;
}
bool arrange[500];
int main() {
    cin >> n;
    for (int i = 0; i < n; i++)
        arrange[i] = false;
    for (int i = 0; i < n; i++)
        cin >> games[i].T;
    for (int i = 0; i < n; i++)
        cin >> games[i].R;
    sort(games, games + n, game_cmp);
    int sum = 0;
    for (int i = 0; i < n; i++) {
        for (int t = games[i].T - 1; t >= 0; t--)
            if (!arrange[t]) {
                arrange[t] = true;
                sum += games[i].R;
                break;
            }
    }
    cout << sum << endl;
    return 0;
}
